export type RuntimeState = {
  worldId: string
  sceneId: string
}

export function createRuntime(worldId: string, sceneId: string): RuntimeState {
  return { worldId, sceneId }
}

import { parse } from 'yaml'

export type WorldManifest = {
  id: string
  title: string
  startingScene: string
}

export function loadWorldFromYaml(source: string): WorldManifest {
  const data = parse(source) as Record<string, unknown>
  for (const key of ['id', 'title', 'startingScene'] as const) {
    if (typeof data[key] !== 'string' || data[key] === '') {
      throw new Error(`world.yaml missing string field: ${key}`)
    }
  }
  return {
    id: data.id as string,
    title: data.title as string,
    startingScene: data.startingScene as string,
  }
}

package main

import (
  "fmt"
  "io/fs"

  "gopkg.in/yaml.v3"
)

type WorkerAgentConfig struct {
  Command string `yaml:"command"`
}

type WorkerExecutionConfig struct {
  TimeoutSeconds int `yaml:"timeout_seconds"`
}

type WorkerConfig struct {
  RepoPath    string                `yaml:"repo_path"`
  WorktreeDir string                `yaml:"worktree_dir"`
  Agent       WorkerAgentConfig     `yaml:"agent"`
  Execution   WorkerExecutionConfig `yaml:"execution"`
}

func LoadWorkerFS(fsys fs.FS, name string) (*WorkerConfig, error) {
  f, err := fsys.Open(name)
  if err != nil {
    return nil, err
  }
  defer f.Close()
  var cfg WorkerConfig
  if err := yaml.NewDecoder(f).Decode(&cfg); err != nil {
    return nil, err
  }
  if cfg.RepoPath == "" {
    return nil, fmt.Errorf("repo_path is required")
  }
  if cfg.Agent.Command == "" {
    return nil, fmt.Errorf("agent.command is required")
  }
  if cfg.Execution.TimeoutSeconds <= 0 {
    return nil, fmt.Errorf("execution.timeout_seconds must be > 0")
  }
  return &cfg, nil
}

